package com.crmconnect.connection;
import com.crmconnect.common.BaseEntity; import jakarta.persistence.*; import org.hibernate.annotations.Filter; import org.hibernate.annotations.FilterDef; import org.hibernate.annotations.ParamDef;
@Entity @Table(name="connections") @FilterDef(name="tenantFilter",parameters=@ParamDef(name="tenantId",type=Long.class)) @Filter(name="tenantFilter",condition="tenant_id = :tenantId") public class Connection extends BaseEntity { private Long tenantId; private String firstName,lastName,email,phone,companyName; @Enumerated(EnumType.STRING) private Source source; @Enumerated(EnumType.STRING) private Status status; private Long assignedToUserId; public enum Source{WEBSITE,REFERRAL,ADS,OTHER} public enum Status{LEAD,QUALIFIED,CUSTOMER} public Long getTenantId(){return tenantId;} public void setTenantId(Long v){tenantId=v;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getCompanyName(){return companyName;} public void setCompanyName(String v){companyName=v;} public Source getSource(){return source;} public void setSource(Source v){source=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} public Long getAssignedToUserId(){return assignedToUserId;} public void setAssignedToUserId(Long v){assignedToUserId=v;} }
